CREATE TABLE IF NOT EXISTS notification_deliveries (id VARCHAR(36) PRIMARY KEY, team_id VARCHAR(36) NOT NULL, event_seq BIGINT NOT NULL, member_id VARCHAR(36) NOT NULL, channel VARCHAR(16) NOT NULL, kind VARCHAR(24) NOT NULL, title VARCHAR(120) NOT NULL, body VARCHAR(200) NOT NULL, session_id VARCHAR(36) NULL, wait_id VARCHAR(36) NULL, collapse_key VARCHAR(80) NOT NULL, `state` VARCHAR(16) NOT NULL, attempts INT NOT NULL, next_attempt_at BIGINT NOT NULL, lease_until BIGINT NOT NULL, last_error VARCHAR(40) NULL, created_at BIGINT NOT NULL, delivered_at BIGINT NULL, CONSTRAINT notification_deliveries_member FOREIGN KEY (member_id) REFERENCES members(id) ON DELETE CASCADE);
ALTER TABLE notification_deliveries ADD CONSTRAINT notification_delivery_event UNIQUE (team_id, event_seq, member_id, channel);
CREATE INDEX notification_delivery_due ON notification_deliveries (`state`, next_attempt_at, lease_until);
CREATE INDEX notification_delivery_retention ON notification_deliveries (created_at);